insert into public.missions(id, template) values
('photo-time', '{"id":"photo-time","version":1,"title":"1년 전의 나 만나기","emoji":"📸","shortDescription":"사진첩 속 잊고 있던 하루를 꺼내요.","fullDescription":"사진첩에서 작년 이맘때 사진 하나를 찾아보세요. 사진이 없다면 기억에 남는 사진도 좋아요. 그날의 나에게 짧은 제목을 붙여보세요.","category":"photo","allowedRelationships":["solo","friend","couple","family"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["지난 사진 한 장 고르기","그날 기억나는 것 하나 떠올리기","사진에 오늘의 제목 붙이기"],"constraints":["공개하거나 공유할 필요는 없어요","불편하면 언제든 멈춰도 좋아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('three-colors', '{"id":"three-colors","version":1,"title":"오늘의 색 세 개 찾기","emoji":"🎨","shortDescription":"익숙한 공간도 색으로 보면 달라져요.","fullDescription":"편한 자리에서 주변을 둘러보세요. 눈에 들어오는 색 세 개를 골라 오늘의 기분에 어울리는 이름을 붙여봐요. 사진이나 준비물 없이도 할 수 있어요.","category":"creative","allowedRelationships":["solo","friend","couple","family"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["주변에서 색 세 개 찾기","각 색에 기분 이름 붙이기","오늘을 대표할 색 하나 고르기"],"constraints":["공개하거나 공유할 필요는 없어요","불편하면 언제든 멈춰도 좋아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('one-song', '{"id":"one-song","version":1,"title":"한 곡만 제대로 듣기","emoji":"🎧","shortDescription":"스크롤은 잠깐 멈추고, 좋아하는 노래 한 곡.","fullDescription":"이미 들을 수 있는 좋아하는 노래 한 곡을 재생해요. 휴대폰 화면을 내려놓고 평소 놓쳤던 악기나 가사 하나를 찾아보세요.","category":"home","allowedRelationships":["solo","friend","couple","family"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["무료로 들을 수 있는 노래 고르기","편안한 음량으로 한 곡 듣기","새롭게 들린 부분 하나 떠올리기"],"constraints":["새 결제나 구독은 하지 않아요","주변에 방해되지 않는 작은 음량으로 들어요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('object-museum', '{"id":"object-museum","version":1,"title":"내 방의 작은 박물관","emoji":"🏺","shortDescription":"평범한 물건 하나를 오늘의 전시품으로.","fullDescription":"손이 닿는 곳의 내 물건 하나를 골라요. 이 물건이 박물관에 있다면 어떤 이름과 설명이 붙을까요? 거창할수록 재밌어요.","category":"creative","allowedRelationships":["solo","friend","couple","family"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":2,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["내 물건 하나 고르기","멋진 전시 제목 짓기","소개 문장 한 줄 만들어보기"],"constraints":["공개하거나 공유할 필요는 없어요","불편하면 언제든 멈춰도 좋아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('movie-title', '{"id":"movie-title","version":1,"title":"오늘을 영화로 만든다면","emoji":"🎬","shortDescription":"아주 평범했던 오늘에 대작의 제목을 붙여요.","fullDescription":"오늘 있었던 사소한 일을 하나 떠올려요. 그 일을 소재로 영화 제목과 예고편 첫 문장을 만들어보세요. 함께라면 번갈아 감독이 되어봐요.","category":"creative","allowedRelationships":["solo","friend","couple","family"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":3,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["오늘의 작은 사건 고르기","영화 장르와 제목 정하기","예고편 첫 문장 말해보기"],"constraints":["공개하거나 공유할 필요는 없어요","불편하면 언제든 멈춰도 좋아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('tiny-advert', '{"id":"tiny-advert","version":1,"title":"물건 하나, 전설의 광고","emoji":"📣","shortDescription":"평범한 물건을 세기의 발명품처럼 소개해요.","fullDescription":"내 물건 하나를 골라 20초짜리 광고를 만들어봐요. 혼자라면 속으로, 함께라면 돌아가며 소개해요. 녹화하거나 공개할 필요는 없어요.","category":"challenge","allowedRelationships":["solo","friend","couple","family"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":4,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":2,"estimatedFun":4,"baseExp":100,"steps":["안전한 내 물건 하나 고르기","과장된 장점 세 가지 상상하기","20초 광고를 작게 말하거나 속으로 해보기"],"constraints":["공개하거나 공유할 필요는 없어요","불편하면 언제든 멈춰도 좋아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('five-questions', '{"id":"five-questions","version":1,"title":"우리가 몰랐던 다섯 가지","emoji":"💬","shortDescription":"자주 만나는 사이에도 처음 듣는 이야기가 있어요.","fullDescription":"요즘 좋아하는 간식, 가보고 싶은 곳, 기억나는 장면, 배우고 싶은 것, 오늘 좋았던 일. 다섯 주제를 돌아가며 이야기해요.","category":"conversation","allowedRelationships":["friend","couple","family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["질문 하나씩 돌아가며 고르기","서로의 답을 끊지 않고 듣기","새로 알게 된 것 하나 말해주기"],"constraints":["말하고 싶지 않은 질문은 건너뛰어요","개인정보나 비밀을 요구하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('family-memory', '{"id":"family-memory","version":1,"title":"우리 집 추억 퀴즈","emoji":"🏡","shortDescription":"같은 추억, 서로 다른 기억.","fullDescription":"모두가 편하게 기억하는 즐거운 가족 추억 하나를 골라요. 그날의 음식이나 장소로 가벼운 퀴즈를 내보세요.","category":"game","allowedRelationships":["family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":2,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["즐거운 추억 하나 고르기","서로에게 퀴즈 한 문제 내기","가장 웃긴 기억 함께 이야기하기"],"constraints":["공개하거나 공유할 필요는 없어요","불편하면 언제든 멈춰도 좋아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('compliment', '{"id":"compliment","version":1,"title":"너의 숨은 장점 발견","emoji":"💜","shortDescription":"너무 익숙해서 말하지 않았던 좋은 점.","fullDescription":"상대에게 고마웠던 작은 행동 하나를 구체적으로 떠올려요. 서로 한 문장씩 알려주고 어떤 순간이었는지 이야기해봐요.","category":"date","allowedRelationships":["couple","friend","family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["고마웠던 순간 하나 떠올리기","어떤 점이 좋았는지 말해주기","상대의 이야기 듣기"],"constraints":["공개하거나 공유할 필요는 없어요","불편하면 언제든 멈춰도 좋아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('tiny-tidy', '{"id":"tiny-tidy","version":1,"title":"딱 한 칸만 정리하기","emoji":"🧺","shortDescription":"방 전체 말고, 손바닥만 한 영역부터.","fullDescription":"책상 한쪽이나 서랍 한 칸을 골라요. 내 물건 다섯 개만 제자리로 옮겨봐요. 대청소로 커지지 않게 작게 끝내세요.","category":"home","allowedRelationships":["solo","friend","couple","family"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":2,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["아주 작은 영역 정하기","내 물건 다섯 개 제자리로 옮기기","정리된 자리를 보고 끝내기"],"constraints":["무거운 가구나 날카로운 물건은 옮기지 않아요","다른 사람의 물건은 건드리지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('silly-story', '{"id":"silly-story","version":1,"title":"한 문장씩 엉뚱한 이야기","emoji":"🛸","shortDescription":"주인공은 양말. 목적지는 우주.","fullDescription":"양말이 우주로 떠났다는 문장으로 시작해요. 혼자라면 이어서, 함께라면 한 사람씩 문장을 더해 총 다섯 문장의 이야기를 완성해요.","category":"game","allowedRelationships":["solo","friend","couple","family"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":3,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":4,"baseExp":100,"steps":["양말 주인공 이름 짓기","이야기 다섯 문장 이어가기","엉뚱한 결말 붙이기"],"constraints":["공개하거나 공유할 필요는 없어요","불편하면 언제든 멈춰도 좋아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('photo-theme', '{"id":"photo-theme","version":1,"title":"우리 집에서 동그라미 수집","emoji":"🟠","shortDescription":"동그란 것 세 개, 발견하면 성공.","fullDescription":"집 안에서 안전하게 손이 닿는 곳의 동그란 물건 세 개를 찾아요. 사진으로 담거나 눈으로만 모아도 좋아요.","category":"photo","allowedRelationships":["solo","friend","couple","family"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":2,"intensity":2,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["첫 번째 동그라미 찾기","서로 다른 동그라미 두 개 더 찾기","가장 의외였던 물건 고르기"],"constraints":["높은 곳에 올라가거나 물건을 옮기지 않아요","사진에 주소나 개인정보가 나오지 않게 해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('nearby-walk', '{"id":"nearby-walk","version":1,"title":"익숙한 길의 새로운 장면","emoji":"🌿","shortDescription":"늘 지나던 길에서 놓친 것 세 개 찾기.","fullDescription":"집 근처 익숙하고 사람이 다니는 보행로로 잠깐 나가요. 간판의 글씨, 나무의 모양, 건물의 색처럼 처음 눈에 들어오는 것 세 개를 찾아 돌아오세요.","category":"walk","allowedRelationships":["solo","friend","couple","family"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":1,"travelScope":"nearby","indoor":false,"outdoor":true,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["날씨와 밝은 보행로 확인하기","10분 이내 거리에서 새 장면 세 개 찾기","익숙한 길로 돌아오기"],"constraints":["비·더위 등 걷기 불편한 날씨에는 진행하지 않아요","차도·외진 길·사유지는 들어가지 않아요","걷는 중에는 휴대폰을 보지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('snack-pick', '{"id":"snack-pick","version":1,"title":"5천 원 간식 탐험","emoji":"🍪","shortDescription":"늘 집던 간식 대신, 처음 보는 맛 하나.","fullDescription":"왕복 10분 안의 익숙한 가게가 열려 있는지 확인해요. 5천 원 안에서 평소 안 먹던 간식 하나를 골라 편한 곳에서 맛보세요.","category":"food","allowedRelationships":["solo","friend","couple","family"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":5000,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":2,"travelScope":"nearby","indoor":true,"outdoor":false,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["가까운 가게의 이용 가능 여부 확인하기","가격과 성분을 확인해 간식 하나 고르기","편한 곳에서 맛보고 한 줄 평 남기기"],"constraints":["알레르기·식이 제한이 있는 성분은 피해요","술이나 연령 제한 상품은 제외해요","가게가 닫혔거나 멀면 다른 미션을 골라요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('menu-swap', '{"id":"menu-swap","version":1,"title":"서로의 간식 골라주기","emoji":"🥨","shortDescription":"상대가 좋아할 뜻밖의 맛을 찾아요.","fullDescription":"왕복 10분 이내의 익숙한 가게가 열려 있다면, 각자 5천 원 이하에서 상대를 위한 간식 하나를 골라봐요. 먼저 못 먹는 재료를 알려주세요.","category":"food","allowedRelationships":["friend","couple","family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":5000,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":3,"travelScope":"nearby","indoor":true,"outdoor":false,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["못 먹는 재료와 예산 확인하기","가격표를 보고 서로의 간식 고르기","고른 이유를 말하며 맛보기"],"constraints":["예산은 1인당 5,000원 이하예요","알레르기 성분이나 싫다는 음식은 고르지 않아요","술은 제외하고 가게 이용이 어려우면 다른 미션을 골라요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('future-postcard', '{"id":"future-postcard","version":1,"title":"다음 달의 나에게 한 줄","emoji":"✉️","shortDescription":"거창한 다짐 대신, 다정한 안부.","fullDescription":"휴대폰 메모에 다음 달의 나에게 짧은 편지를 써봐요. 요즘 좋아하는 것 하나와 해보고 싶은 작은 일 하나면 충분해요.","category":"creative","allowedRelationships":["solo","friend","couple","family"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["메모 열기","요즘 좋아하는 것과 작은 소망 적기","다음 달의 나에게 제목 붙이기"],"constraints":["공개하거나 공유할 필요는 없어요","불편하면 언제든 멈춰도 좋아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('book-chapter', '{"id":"book-chapter","version":1,"title":"책 한 챕터만","emoji":"📖","shortDescription":"완독 말고, 오늘은 한 장면만 가져와요.","fullDescription":"이미 가진 책이나 무료로 공개된 글을 골라요. 20분 안에 읽을 수 있는 한 챕터를 읽고 마음에 남은 문장 하나를 메모해요. 길면 한 페이지로 줄여도 좋아요.","category":"home","allowedRelationships":["solo"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["무료로 읽을 글 고르기","한 챕터 또는 한 페이지 읽기","마음에 남은 문장 메모하기"],"constraints":["공개하거나 공유할 필요는 없어요","불편하면 언제든 멈춰도 좋아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('playlist-walk', '{"id":"playlist-walk","version":1,"title":"플레이리스트 한 바퀴","emoji":"🎵","shortDescription":"익숙한 산책길에 오늘의 배경음악을.","fullDescription":"무료로 들을 수 있는 노래 세 곡을 고른 뒤 익숙한 보행로를 짧게 걸어요. 주변 소리가 잘 들리는 작은 음량으로 듣고 10분 거리 안에서 원래 길로 돌아와요.","category":"walk","allowedRelationships":["solo"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":2,"travelScope":"nearby","indoor":false,"outdoor":true,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["서서 노래 세 곡 준비하기","밝은 보행로에서 짧게 걷기","원래 길로 돌아와 가장 어울린 곡 고르기"],"constraints":["밝고 사람이 다니는 익숙한 보행로에서만 진행해요","날씨가 불편하면 멈추고 차도·외진 길·사유지는 피해요","걸을 때는 휴대폰을 보지 않고 원래 길로 돌아와요","음량은 작게, 주변 소리를 차단하는 이어폰 설정은 꺼요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('cafe-photo-sort', '{"id":"cafe-photo-sort","version":1,"title":"카페에서 사진 열 장 정리","emoji":"☕","shortDescription":"커피 한 잔, 사진첩의 작은 정리.","fullDescription":"도보 왕복 20분 안에 이용 가능한 카페를 확인해요. 1만 원 이하 음료를 주문하고 내 사진 열 장을 작은 앨범에 모아요. 사진을 삭제하거나 올릴 필요는 없어요.","category":"photo","allowedRelationships":["solo"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":10000,"minDuration":30,"maxDuration":60,"energyLevel":2,"intensity":1,"travelScope":"nearby","indoor":true,"outdoor":false,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":true,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["가까운 카페의 자리와 가격 확인하기","예산 안에서 음료 주문하기","내 사진 열 장을 새 앨범에 모으고 돌아오기"],"constraints":["가격과 알레르기·식이 제한 성분을 먼저 확인해요","술이나 연령 제한 상품은 제외해요","가까운 가게가 열려 있고 예산 안에 살 수 있을 때만 진행해요","타인의 얼굴이나 내 개인정보가 보이는 화면을 주변에 공개하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('local-sign-discovery', '{"id":"local-sign-discovery","version":1,"title":"동네의 처음 본 간판","emoji":"🔎","shortDescription":"새로운 장소는 생각보다 가까워요.","fullDescription":"늘 다니는 밝은 길에서 처음 눈에 들어온 가게나 공공시설의 간판 하나를 찾아요. 보행로에서 이름만 기억하고 돌아와 왜 눈에 띄었는지 적어요. 들어가거나 구매할 필요는 없어요.","category":"exploration","allowedRelationships":["solo"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":3,"travelScope":"nearby","indoor":false,"outdoor":true,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["왕복 가능한 익숙한 길 고르기","처음 눈에 들어온 간판 이름 기억하기","돌아와 이름과 발견한 이유 적기"],"constraints":["밝고 사람이 다니는 익숙한 보행로에서만 진행해요","날씨가 불편하면 멈추고 차도·외진 길·사유지는 피해요","걸을 때는 휴대폰을 보지 않고 원래 길로 돌아와요","문을 열고 들어가거나 사람을 촬영하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('online-gallery', '{"id":"online-gallery","version":1,"title":"무료 전시, 화면으로 한 바퀴","emoji":"🖼️","shortDescription":"무료 공개 전시에서 마음에 드는 작품 하나.","fullDescription":"공공 미술관이나 박물관의 공식 홈페이지에서 무료로 공개한 온라인 전시를 찾아요. 작품 세 개를 보고 가장 마음에 드는 하나에 내 방식의 제목을 붙여요.","category":"exploration","allowedRelationships":["solo"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":2,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["공식 홈페이지의 무료 온라인 전시 찾기","공개된 작품 세 개 살펴보기","가장 마음에 든 작품에 내 제목 붙이기"],"constraints":["로그인·결제·파일 설치를 요구하는 전시는 건너뛰어요","작품은 감상하고 무단으로 재배포하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('window-weather', '{"id":"window-weather","version":1,"title":"창밖을 보는 5분","emoji":"☁️","shortDescription":"화면 대신 오늘의 하늘을 봐요.","fullDescription":"편한 실내 자리에서 닫힌 창 너머의 하늘이나 건물을 바라봐요. 눈에 들어오는 모양 두 개를 찾고 오늘의 날씨에 별명을 붙여요. 창이 없다면 주변의 빛과 그림자를 봐도 좋아요.","category":"home","allowedRelationships":["solo"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["실내의 편한 자리 찾기","모양이나 그림자 두 개 발견하기","오늘의 빛에 별명 붙이기"],"constraints":["창문 밖으로 몸을 내밀거나 난간에 기대지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('no-heat-snack', '{"id":"no-heat-snack","version":1,"title":"불 없이 간식 조합","emoji":"🥣","shortDescription":"있는 재료 두 개로 작은 실험.","fullDescription":"이미 먹어도 되는 준비된 음식이나 간식 두 가지를 골라 소량씩 조합해봐요. 요거트와 과자처럼 칼·불·가열이 필요 없는 조합만 사용해요. 재료가 하나뿐이면 먹는 순서만 바꿔봐요.","category":"food","allowedRelationships":["solo"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":2,"intensity":2,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["유통기한과 성분 확인하기","바로 먹을 수 있는 재료 소량 조합하기","맛보고 조합에 이름 붙이기"],"constraints":["날고기·상한 재료·알레르기 성분은 제외해요","칼·불·뜨거운 물을 사용하지 않고 어린이는 보호자와 함께해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('one-line-drawing', '{"id":"one-line-drawing","version":1,"title":"한 줄로 그리는 자화상","emoji":"✏️","shortDescription":"잘 그리는 게 아니라 끝까지 한 줄로.","fullDescription":"종이와 펜 또는 이미 쓰는 그림 앱으로 내 얼굴을 한 줄로 그려봐요. 손을 떼지 않는다는 가벼운 규칙만 지키면 돼요. 완성한 그림에 우스운 작품명을 붙여봐요.","category":"creative","allowedRelationships":["solo"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":3,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["종이나 기존 그림 도구 준비하기","손을 떼지 않고 얼굴 그리기","작품명 붙이기"],"constraints":["새 앱 설치나 결제 없이 가능한 도구만 사용해요","다른 사람의 얼굴을 허락 없이 올리지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('park-bench', '{"id":"park-bench","version":1,"title":"공원 벤치의 짧은 휴식","emoji":"🌳","shortDescription":"멀리 가지 않고 바깥 공기 한 번.","fullDescription":"왕복 20분 안의 익숙한 공원이나 공개된 쉼터가 이용 가능한지 확인해요. 편한 자리에 잠깐 앉아 주변 색 세 가지를 찾고 같은 길로 돌아와요.","category":"walk","allowedRelationships":["solo"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":1,"travelScope":"nearby","indoor":false,"outdoor":true,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":true,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["가까운 공개 쉼터와 날씨 확인하기","편한 자리에서 주변 색 세 가지 찾기","익숙한 길로 돌아오기"],"constraints":["밝고 사람이 다니는 익숙한 보행로에서만 진행해요","날씨가 불편하면 멈추고 차도·외진 길·사유지는 피해요","걸을 때는 휴대폰을 보지 않고 원래 길로 돌아와요","닫힌 공원이나 출입 제한 구역은 들어가지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('gentle-stretch', '{"id":"gentle-stretch","version":1,"title":"앉아서 어깨 쉬어가기","emoji":"🧘","shortDescription":"땀나는 운동 대신 편한 범위로.","fullDescription":"안정된 의자에 앉아 편하게 호흡해요. 어깨를 천천히 올렸다 내리고 손가락을 가볍게 펴봐요. 통증 없는 범위에서만 하고 불편하면 움직이지 않고 쉬어도 좋아요.","category":"home","allowedRelationships":["solo"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":2,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["안정된 자리에 앉기","통증 없는 범위에서 어깨와 손 가볍게 움직이기","편한 호흡으로 마무리하기"],"constraints":["통증·어지러움이 있으면 즉시 멈춰요","균형 잡기·목 과하게 꺾기·힘으로 버티는 동작은 하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('random-word-cover', '{"id":"random-word-cover","version":1,"title":"랜덤 단어로 앨범 커버","emoji":"💿","shortDescription":"지금 보이는 물건이 내 데뷔 앨범 제목.","fullDescription":"편한 자리에서 눈에 들어온 내 물건 이름 하나를 골라요. 그 단어가 앨범 제목이라면 어떤 음악일지 상상하고 커버를 메모나 종이에 그려봐요. 공개하지 않아도 데뷔 완료예요.","category":"random","allowedRelationships":["solo"],"minPeople":1,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":4,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":2,"estimatedFun":4,"baseExp":100,"steps":["눈에 들어온 물건 이름 고르기","앨범 장르와 수록곡 제목 상상하기","글이나 그림으로 커버 완성하기"],"constraints":["공개하거나 공유할 필요는 없어요","불편하면 언제든 멈춰도 좋아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('friend-small-gift', '{"id":"friend-small-gift","version":1,"title":"5천 원 선물 챌린지","emoji":"🎁","shortDescription":"가격보다 고른 이유가 중요한 선물.","fullDescription":"왕복 10분 안에 열린 익숙한 가게에서 각자 5천 원 이하의 작은 물건을 골라요. 구매 전 서로 받아도 괜찮은지 확인하고 고른 이유와 함께 건네봐요.","category":"shopping","allowedRelationships":["friend"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":5000,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":2,"travelScope":"nearby","indoor":true,"outdoor":false,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":true,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["선물 받아도 되는지와 예산 확인하기","가격표를 보고 작은 물건 고르기","고른 이유와 함께 선물 건네기"],"constraints":["1인당 5,000원 이하, 구매는 서로 동의했을 때만 해요","연령 제한 상품·날카로운 물건·살아 있는 동물은 제외해요","예산 안의 가게가 이용 가능할 때만 진행해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('friend-photo-theme', '{"id":"friend-photo-theme","version":1,"title":"같은 주제, 다른 사진","emoji":"📷","shortDescription":"주제는 그림자. 결과는 각자의 시선.","fullDescription":"그림자나 파란색 같은 주제를 하나 정해요. 함께 익숙한 보행로를 걸으며 안전하게 멈춘 자리에서 각자 사진 한 장을 찍고 보여줘요. 사진 대신 발견한 장면을 말해도 좋아요.","category":"photo","allowedRelationships":["friend"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":3,"travelScope":"nearby","indoor":false,"outdoor":true,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["주제 하나와 짧은 왕복 길 정하기","서서 각자의 장면 한 개 담기","함께 돌아와 발견한 차이 말하기"],"constraints":["밝고 사람이 다니는 익숙한 보행로에서만 진행해요","날씨가 불편하면 멈추고 차도·외진 길·사유지는 피해요","걸을 때는 휴대폰을 보지 않고 원래 길로 돌아와요","다른 사람 얼굴·차량 번호·주소는 사진에서 제외해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('friend-coin-walk', '{"id":"friend-coin-walk","version":1,"title":"동전이 고르는 짧은 산책","emoji":"🪙","shortDescription":"선택은 동전에게, 안전한 길은 우리에게.","fullDescription":"익숙한 보행로의 안전한 두 방향 중 하나를 동전으로 정해요. 두 번까지만 방향을 정하고 10분 거리 안에서 같은 길로 돌아와요. 동전이 없으면 가위바위보로 정해도 좋아요.","category":"walk","allowedRelationships":["friend"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":3,"travelScope":"nearby","indoor":false,"outdoor":true,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["안전하고 공개된 두 길 확인하기","멈춘 자리에서 방향을 두 번까지만 정하기","10분 거리 안에서 원래 길로 돌아오기"],"constraints":["밝고 사람이 다니는 익숙한 보행로에서만 진행해요","날씨가 불편하면 멈추고 차도·외진 길·사유지는 피해요","걸을 때는 휴대폰을 보지 않고 원래 길로 돌아와요","차도·계단·골목·출입 제한 방향은 추첨 전에 제외해요","불편한 방향이면 결과를 따르지 않아도 돼요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('friend-paper-game', '{"id":"friend-paper-game","version":1,"title":"종이 한 장 보드게임","emoji":"🎲","shortDescription":"준비물은 메모, 규칙은 우리가 만들어요.","fullDescription":"종이나 공동으로 볼 수 있는 메모에 세 칸짜리 빙고판을 만들어요. 좋아하는 음식 세 개를 적고 돌아가며 이름을 말해 빙고를 해봐요. 여러 명이면 모두가 차례를 가질 수 있게 해요.","category":"game","allowedRelationships":["friend"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":1,"intensity":2,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["각자 음식 세 개로 작은 빙고판 만들기","돌아가며 음식 이름 부르기","한 판 끝내고 가장 의외인 음식 말하기"],"constraints":["벌칙·금전 내기 없이 가볍게 한 판만 해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('friend-playlist-exchange', '{"id":"friend-playlist-exchange","version":1,"title":"서로의 오늘 노래","emoji":"🎶","shortDescription":"친구가 고른 노래로 기분 읽기.","fullDescription":"무료로 들을 수 있는 노래를 각자 한 곡씩 추천해요. 일부 또는 한 곡을 작은 음량으로 함께 듣고 왜 오늘 이 노래인지 이야기해요. 곡이 길면 1분씩만 들어도 좋아요.","category":"conversation","allowedRelationships":["friend"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["각자 무료로 들을 곡 고르기","돌아가며 짧게 듣기","곡을 고른 이유 이야기하기"],"constraints":["주변에 방해되지 않는 음량으로 듣고 계정이나 비밀번호는 공유하지 않아요","새 구독·결제는 하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('friend-genre-roulette', '{"id":"friend-genre-roulette","version":1,"title":"짧은 영상 장르 룰렛","emoji":"🎞️","shortDescription":"오늘의 장르는 서로 안 고르던 것.","fullDescription":"이미 무료로 볼 수 있는 전체 이용가 짧은 영상 중 코미디·다큐·애니메이션을 후보로 정해요. 가위바위보로 장르를 하나 고르고 30분 이내 영상을 함께 본 뒤 한 줄 평을 말해요.","category":"random","allowedRelationships":["friend"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":30,"maxDuration":60,"energyLevel":1,"intensity":2,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["무료·전체 이용가 후보 세 장르 확인하기","가위바위보로 한 장르 고르기","30분 이내 영상 보고 한 줄 평 말하기"],"constraints":["합법적으로 공개된 영상만 보고 유료 결제나 계정 공유는 하지 않아요","불편한 내용이면 언제든 중단해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('friend-description-draw', '{"id":"friend-description-draw","version":1,"title":"설명만 듣고 그리기","emoji":"🖍️","shortDescription":"친구의 설명과 내 그림은 얼마나 다를까?","fullDescription":"한 명이 손이 닿는 자신의 물건 하나를 고르고 모양만 설명해요. 나머지는 이름을 모른 채 종이나 기존 그림 앱에 그려봐요. 원본을 공개하고 역할을 바꿔 한 번 더 해요.","category":"creative","allowedRelationships":["friend"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":3,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["설명할 내 물건 하나 고르기","이름 없이 모양을 설명하고 그리기","결과를 보고 역할 바꾸기"],"constraints":["새 도구를 사거나 앱을 설치하지 않아요","서로의 그림을 비웃거나 허락 없이 공개하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('friend-snack-review', '{"id":"friend-snack-review","version":1,"title":"간식 심사위원단","emoji":"🍿","shortDescription":"집에 있는 간식에 아주 진지한 한 줄 평.","fullDescription":"함께 먹어도 되는 이미 가진 간식 하나를 소량씩 맛봐요. 식감과 향을 과장된 심사평으로 표현해요. 간식이 없다면 물 한 모금의 온도와 느낌으로 심사해도 좋아요.","category":"food","allowedRelationships":["friend"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":3,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["공유 동의와 성분 확인하기","간식 소량 또는 물 맛보기","각자 심사평 한 문장 말하기"],"constraints":["알레르기·식이 제한·유통기한을 확인해요","많이 먹기 경쟁이나 음식 강요는 하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('friend-quiet-charades', '{"id":"friend-quiet-charades","version":1,"title":"무음 영화 주인공","emoji":"🤫","shortDescription":"말 없이 표정과 손짓으로만.","fullDescription":"편한 자리에서 고양이·우산·커피처럼 쉬운 단어를 표정과 작은 손짓으로 표현해요. 다른 사람은 단어를 맞히고 돌아가며 한 번씩 해봐요. 큰 동작 없이 앉아서 해도 돼요.","category":"game","allowedRelationships":["friend"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":2,"intensity":4,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":false,"difficulty":2,"estimatedFun":4,"baseExp":100,"steps":["쉬운 단어 세 개 정하기","앉아서 표정과 손짓으로 표현하기","서로 한 번씩 맞히고 마무리하기"],"constraints":["뛰기·넘어지기·가구에 올라가기·큰 소리는 하지 않아요","벌칙과 촬영 없이 진행해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
