('friend-block-explore', '{"id":"friend-block-explore","version":1,"title":"우리 동네 한 블록 탐방","emoji":"🧭","shortDescription":"낯선 먼 곳보다 익숙한 한 블록.","fullDescription":"집 근처 익숙한 공개 보행로 한 블록을 정해요. 함께 걸으며 간판·나무·건물 색 중 하나씩 눈여겨보고 다시 출발점으로 돌아와 서로의 발견을 이야기해요.","category":"exploration","allowedRelationships":["friend"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":30,"maxDuration":60,"energyLevel":2,"intensity":2,"travelScope":"nearby","indoor":false,"outdoor":true,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["왕복 30분 이내 공개 길 정하기","각자 다른 종류의 장면 하나 발견하기","출발점으로 돌아와 발견 공유하기"],"constraints":["밝고 사람이 다니는 익숙한 보행로에서만 진행해요","날씨가 불편하면 멈추고 차도·외진 길·사유지는 피해요","걸을 때는 휴대폰을 보지 않고 원래 길로 돌아와요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('couple-menu-date', '{"id":"couple-menu-date","version":1,"title":"오늘의 메뉴는 네가 골라줘","emoji":"🍜","shortDescription":"상대의 취향을 믿고 주문 한 번.","fullDescription":"도보 왕복 20분 안의 이용 가능한 식당에서 1인당 1만 5천 원 이하 메뉴를 서로 골라줘요. 못 먹는 재료와 싫은 음식은 먼저 알려주고 주문 전 최종 동의를 받아요.","category":"food","allowedRelationships":["couple"],"minPeople":2,"maxPeople":2,"minBudget":0,"maxBudget":15000,"minDuration":30,"maxDuration":60,"energyLevel":2,"intensity":2,"travelScope":"nearby","indoor":true,"outdoor":false,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":true,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["가까운 식당의 가격·자리·식이 제한 확인하기","서로 메뉴를 골라 동의 받고 주문하기","먹으며 선택한 이유 말하기"],"constraints":["가격과 알레르기·식이 제한 성분을 먼저 확인해요","술이나 연령 제한 상품은 제외해요","가까운 가게가 열려 있고 예산 안에 살 수 있을 때만 진행해요","1인당 15,000원 안에 이용 가능한 식당에서만 해요","상대가 싫다는 메뉴는 주문하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('couple-window-shopping', '{"id":"couple-window-shopping","version":1,"title":"너에게 어울리는 물건 찾기","emoji":"🛍️","shortDescription":"사지 않아도 재밌는 취향 탐험.","fullDescription":"왕복 10분 안의 공개된 상점가를 구경해요. 진열된 물건 중 상대에게 어울리는 것 하나를 각자 고르고 이유를 말해줘요. 구매 없이 눈으로 보는 미션이에요.","category":"shopping","allowedRelationships":["couple"],"minPeople":2,"maxPeople":2,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":2,"travelScope":"nearby","indoor":true,"outdoor":false,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":true,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["가까운 구경 가능한 상점가 확인하기","눈으로 상대에게 어울리는 물건 고르기","이유를 말하고 돌아오기"],"constraints":["구매하거나 직원을 촬영할 필요는 없어요","상품을 허락 없이 만지거나 영업을 방해하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('couple-portrait', '{"id":"couple-portrait","version":1,"title":"서로의 표정 한 컷","emoji":"💜","shortDescription":"지금 가장 편한 표정을 남겨요.","fullDescription":"촬영해도 되는지 먼저 물어보고 편한 자리에서 서로 사진 한 장씩 찍어줘요. 촬영이 싫다면 표정을 말이나 그림으로 묘사해도 좋아요. 오늘의 사진에 짧은 제목을 붙여요.","category":"photo","allowedRelationships":["couple"],"minPeople":2,"maxPeople":2,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":2,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["사진 또는 그림에 서로 동의하기","편한 자리에서 각자 표정 담기","서로의 컷에 제목 붙이기"],"constraints":["사진은 당사자 동의 없이 공유하지 않아요","주소나 개인정보가 배경에 보이지 않게 해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('couple-new-neighborhood', '{"id":"couple-new-neighborhood","version":1,"title":"처음 걷는 동네 데이트","emoji":"🚉","shortDescription":"왕복 가능한 가까운 새 동네, 천천히 한 바퀴.","fullDescription":"왕복 대중교통 시간 1시간 이내, 1인 교통비 1만 원 이하인 익숙한 생활권의 새 동네를 골라요. 밝은 공개 상점가를 30분 안에서 구경하고 출발지로 돌아와요. 이동 시간과 비용을 출발 전에 확인해요.","category":"exploration","allowedRelationships":["couple"],"minPeople":2,"maxPeople":2,"minBudget":0,"maxBudget":10000,"minDuration":60,"maxDuration":180,"energyLevel":3,"intensity":3,"travelScope":"far","indoor":false,"outdoor":true,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":true,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["왕복 교통비·소요시간·밝은 상점가 확인하기","공개 보행로에서 짧게 구경하기","정해둔 시간 안에 출발지로 돌아오기"],"constraints":["밝고 사람이 다니는 익숙한 보행로에서만 진행해요","날씨가 불편하면 멈추고 차도·외진 길·사유지는 피해요","걸을 때는 휴대폰을 보지 않고 원래 길로 돌아와요","자가 운전·낯선 사람 차량 탑승·외진 목적지는 제외해요","조건 안의 대중교통과 장소가 이용 가능할 때만 출발해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('couple-dessert', '{"id":"couple-dessert","version":1,"title":"랜덤 디저트, 반씩 나누기","emoji":"🍰","shortDescription":"둘 다 안 먹어본 맛, 하나만.","fullDescription":"왕복 10분 안의 열린 가게에서 함께 먹어도 되는 디저트 후보 두 개를 골라요. 가위바위보로 하나를 정하고 1인당 1만 원 이하에서 나눠 먹어요. 가격과 성분은 먼저 확인해요.","category":"food","allowedRelationships":["couple"],"minPeople":2,"maxPeople":2,"minBudget":0,"maxBudget":10000,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":2,"travelScope":"nearby","indoor":true,"outdoor":false,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":true,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["가까운 가게의 가격과 성분 확인하기","함께 동의한 두 후보에서 하나 고르기","편한 자리에서 나눠 먹고 한 줄 평 말하기"],"constraints":["가격과 알레르기·식이 제한 성분을 먼저 확인해요","술이나 연령 제한 상품은 제외해요","가까운 가게가 열려 있고 예산 안에 살 수 있을 때만 진행해요","먹기 싫은 후보는 추첨에 넣지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('couple-photo-booth', '{"id":"couple-photo-booth","version":1,"title":"사진관에서 오늘의 한 장","emoji":"🎞️","shortDescription":"특별한 날 아니어도, 오늘의 우리.","fullDescription":"도보 왕복 20분 안의 이용 가능한 셀프 사진관을 확인해요. 총액 6만 원 이하, 1인당 3만 원 안에서 가능한 상품과 대기시간을 확인하고 서로 편한 포즈로 사진을 남겨요.","category":"date","allowedRelationships":["couple"],"minPeople":2,"maxPeople":2,"minBudget":5000,"maxBudget":30000,"minDuration":30,"maxDuration":60,"energyLevel":2,"intensity":3,"travelScope":"nearby","indoor":true,"outdoor":false,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":true,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["가격·대기시간·촬영 동의 확인하기","편한 포즈 하나 정해 사진 찍기","사진을 받고 정해진 시간 안에 돌아오기"],"constraints":["대기 포함 1시간·1인 30,000원 안에 이용 가능할 때만 해요","촬영과 보관·공유 범위를 서로 합의하고 타인을 촬영하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('couple-future-date', '{"id":"couple-future-date","version":1,"title":"다음 데이트의 세 가지 소원","emoji":"🗓️","shortDescription":"예약 대신 서로의 취향만 알아봐요.","fullDescription":"다음에 먹고 싶은 음식, 가볍게 가고 싶은 곳, 함께 해보고 싶은 일을 하나씩 말해요. 공통으로 마음에 드는 소원 하나를 메모하고 실제 예약은 하지 않아도 돼요.","category":"conversation","allowedRelationships":["couple"],"minPeople":2,"maxPeople":2,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["각자 세 가지 작은 소원 말하기","상대의 이유 들어보기","공통 소원 하나 메모하기"],"constraints":["공개하거나 공유할 필요는 없어요","불편하면 언제든 멈춰도 좋아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('couple-memory-walk', '{"id":"couple-memory-walk","version":1,"title":"산책하며 꺼내는 첫 기억","emoji":"🌷","shortDescription":"익숙한 길에서 서로의 좋은 기억.","fullDescription":"밝고 익숙한 보행로를 15분 안에서 함께 걸어요. 함께한 즐거운 순간 하나씩을 이야기하고 같은 길로 돌아와 오늘의 산책에 제목을 붙여요.","category":"date","allowedRelationships":["couple"],"minPeople":2,"maxPeople":2,"minBudget":0,"maxBudget":0,"minDuration":30,"maxDuration":60,"energyLevel":2,"intensity":1,"travelScope":"nearby","indoor":false,"outdoor":true,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["짧게 왕복할 밝은 길 고르기","서로의 즐거운 기억 하나씩 듣기","돌아와 산책 제목 정하기"],"constraints":["밝고 사람이 다니는 익숙한 보행로에서만 진행해요","날씨가 불편하면 멈추고 차도·외진 길·사유지는 피해요","걸을 때는 휴대폰을 보지 않고 원래 길로 돌아와요","말하고 싶지 않은 기억은 건너뛰어요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('couple-radio', '{"id":"couple-radio","version":1,"title":"우리 둘만의 라디오","emoji":"📻","shortDescription":"사연은 오늘의 우리, 청취자도 우리.","fullDescription":"서로 오늘의 사소한 사연 하나를 말해요. 한 명은 진행자처럼 사연을 소개하고 다른 한 명은 어울리는 노래 제목을 추천해요. 역할을 바꾸며 작은 라디오를 완성해요.","category":"date","allowedRelationships":["couple"],"minPeople":2,"maxPeople":2,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":4,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":2,"estimatedFun":4,"baseExp":100,"steps":["오늘의 작은 사연 하나씩 고르기","사연을 소개하고 노래 제목 추천하기","역할 바꿔 두 번째 사연 소개하기"],"constraints":["방송·녹음·공개 없이 작은 목소리로 즐겨요","불편한 사연이나 비밀은 요구하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('couple-small-thanks', '{"id":"couple-small-thanks","version":1,"title":"오늘 고마웠던 순간","emoji":"💌","shortDescription":"잘 안 하던 말을 한 문장만.","fullDescription":"오늘 또는 최근 상대가 해준 작은 행동 하나를 떠올려요. 어떤 순간에 고마웠는지 구체적으로 말하고 서로에게 지금 필요한 작은 배려 하나를 물어봐요.","category":"conversation","allowedRelationships":["couple"],"minPeople":2,"maxPeople":2,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["고마웠던 작은 행동 떠올리기","한 문장으로 고마움 전하기","지금 필요한 배려 하나 듣기"],"constraints":["답을 강요하거나 관계를 시험하는 질문은 하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('couple-no-heat-duel', '{"id":"couple-no-heat-duel","version":1,"title":"불 없는 10분 요리 대결","emoji":"🥪","shortDescription":"있는 재료로, 맛보다 이름부터 대결.","fullDescription":"바로 먹어도 되는 준비된 재료만 사용해 10분 동안 각자 작은 간식 조합을 만들어요. 칼과 불은 쓰지 않고 이름과 소개 문장을 붙여요. 재료가 부족하면 만들 조합을 그림으로 표현해요.","category":"challenge","allowedRelationships":["couple"],"minPeople":2,"maxPeople":2,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":3,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":4,"baseExp":100,"steps":["먹을 수 있는 재료와 성분 확인하기","10분 안에 작은 조합 또는 그림 만들기","이름과 소개를 말하고 서로 감상하기"],"constraints":["칼·불·뜨거운 물·날고기는 사용하지 않아요","알레르기와 위생을 확인하고 어린이는 보호자와 함께해요","먹기 강요·많이 먹기·벌칙은 하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('family-photo-album', '{"id":"family-photo-album","version":1,"title":"우리 가족 사진 한 장","emoji":"🖼️","shortDescription":"같이 웃을 수 있는 추억을 꺼내요.","fullDescription":"공유해도 괜찮은 가족 사진 하나를 골라요. 사진이 없으면 함께 즐거웠던 기억을 말해도 좋아요. 각자 그날 기억하는 음식이나 표정을 이야기하고 새 제목을 붙여요.","category":"photo","allowedRelationships":["family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["함께 볼 사진이나 좋은 기억 고르기","각자 기억하는 장면 말하기","사진이나 기억에 새 제목 붙이기"],"constraints":["당사자가 싫어하는 사진이나 기억은 제외해요","사진을 외부에 공개하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('family-food-vote', '{"id":"family-food-vote","version":1,"title":"가족 간식 취향 투표","emoji":"🍎","shortDescription":"의외로 다른 우리 집 간식 순위.","fullDescription":"이미 집에 있는 간식이나 평소 먹고 싶은 간식 세 개를 후보로 정해요. 각자 좋아하는 순서를 말하고 이유를 들어봐요. 실제로 먹거나 새로 구매하지 않아도 돼요.","category":"food","allowedRelationships":["family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["간식 이름 세 개 정하기","각자 좋아하는 순서 말하기","가장 의외인 취향 하나 발견하기"],"constraints":["음식을 먹도록 강요하거나 새로 구매하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('family-small-walk', '{"id":"family-small-walk","version":1,"title":"가족의 느린 한 바퀴","emoji":"👨‍👩‍👧","shortDescription":"가장 천천히 걷는 사람의 속도로.","fullDescription":"모두가 편하게 왕복할 수 있는 밝고 익숙한 길을 골라요. 가장 느린 사람의 속도로 10분 이내 거리만 걷고 오늘 눈에 들어온 색 하나씩을 말하며 돌아와요.","category":"walk","allowedRelationships":["family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":1,"travelScope":"nearby","indoor":false,"outdoor":true,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["모두에게 편한 길과 날씨 확인하기","가장 편한 속도로 짧게 걷기","발견한 색을 말하며 같은 길로 돌아오기"],"constraints":["밝고 사람이 다니는 익숙한 보행로에서만 진행해요","날씨가 불편하면 멈추고 차도·외진 길·사유지는 피해요","걸을 때는 휴대폰을 보지 않고 원래 길로 돌아와요","어린이는 보호자와 함께하고 누군가 힘들면 바로 돌아와요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('family-photo-theme', '{"id":"family-photo-theme","version":1,"title":"가족 사진, 같은 포즈","emoji":"📸","shortDescription":"오늘의 포즈는 작은 손하트.","fullDescription":"사진을 찍어도 되는지 모두에게 물어봐요. 편한 자리에서 같은 표정이나 작은 손짓으로 가족 사진 하나를 남겨요. 촬영이 싫은 사람이 있으면 가족을 간단한 그림으로 그려도 좋아요.","category":"photo","allowedRelationships":["family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":2,"intensity":2,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["사진 또는 그림에 모두 동의하기","앉아서 할 수 있는 작은 포즈 정하기","한 장 남기고 오늘 날짜 적기"],"constraints":["가구에 올라가거나 뛰는 포즈는 하지 않아요","촬영과 외부 공유에 모두의 동의를 받아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('family-taste-quiz', '{"id":"family-taste-quiz","version":1,"title":"우리 가족 취향 퀴즈","emoji":"❓","shortDescription":"가장 좋아하는 색, 알고 있었나요?","fullDescription":"각자 좋아하는 색·계절·음식 중 하나를 마음속으로 정해요. 나머지는 답을 추측하고 돌아가며 출제해요. 맞힌 수보다 새로 알게 된 취향을 이야기해요.","category":"game","allowedRelationships":["family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":1,"intensity":2,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["가벼운 취향 질문 하나 고르기","돌아가며 답 추측하기","새로 알게 된 취향 말해주기"],"constraints":["비밀·개인정보 질문과 틀린 사람의 벌칙은 제외해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('family-pantry-chef', '{"id":"family-pantry-chef","version":1,"title":"냉장고 작은 메뉴 회의","emoji":"🥗","shortDescription":"있는 재료로 만드는 이름부터 맛있는 메뉴.","fullDescription":"보호자가 함께 냉장고의 바로 먹을 수 있는 재료를 확인해요. 칼이나 불 없이 작은 조합을 만들고 모두가 메뉴 이름을 정해봐요. 적당한 재료가 없으면 내일 만들 메뉴를 그림으로 정해도 좋아요.","category":"food","allowedRelationships":["family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":2,"intensity":2,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["보호자와 위생·유통기한·성분 확인하기","안전한 작은 조합 또는 메뉴 그림 만들기","가족이 함께 메뉴 이름 정하기"],"constraints":["칼·불·뜨거운 물·날고기는 사용하지 않아요","어린이는 보호자와 함께하고 알레르기 재료는 제외해요","먹거나 재료를 낭비하도록 강요하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('family-tidy-relay', '{"id":"family-tidy-relay","version":1,"title":"물건 다섯 개 정리 릴레이","emoji":"🧺","shortDescription":"각자 자기 물건만, 딱 다섯 개.","fullDescription":"각자 자신의 가벼운 물건 다섯 개를 원래 자리로 옮겨요. 누가 빨리 하는지 겨루지 않고 다 끝나면 정돈된 공간에 재밌는 이름을 붙여요.","category":"home","allowedRelationships":["family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":2,"intensity":3,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["각자 정리할 가벼운 내 물건 고르기","물건 다섯 개를 원래 자리로 옮기기","함께 공간에 이름 붙이고 끝내기"],"constraints":["무거운 가구·날카로운 물건·다른 사람의 물건은 옮기지 않아요","어린이가 높은 곳에 올라가지 않게 보호자가 함께해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('family-drawing-chain', '{"id":"family-drawing-chain","version":1,"title":"돌아가며 완성하는 그림","emoji":"🎨","shortDescription":"한 사람이 시작하고 모두가 완성해요.","fullDescription":"종이나 이미 사용하는 그림 앱에 첫 사람이 선 하나를 그려요. 돌아가며 조금씩 더해 이상한 동물이나 새 집을 만들어요. 마지막에 모두가 제목을 정해요.","category":"creative","allowedRelationships":["family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":1,"intensity":2,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["그림 주제와 기존 도구 준비하기","한 사람씩 선을 더해 완성하기","모두의 의견으로 제목 붙이기"],"constraints":["어린이는 보호자와 함께하고 서로의 그림을 지우거나 평가하지 않아요","도구 구매나 앱 설치 없이 진행해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('family-playlist', '{"id":"family-playlist","version":1,"title":"세대가 다른 노래 교환","emoji":"🎧","shortDescription":"그 시절의 한 곡과 요즘의 한 곡.","fullDescription":"각자 좋아하는 노래 제목 하나를 말하고 무료로 들을 수 있다면 짧게 함께 들어요. 인원이 많으면 1분씩만 듣고 그 노래를 처음 들은 기억을 이야기해요.","category":"conversation","allowedRelationships":["family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":15,"maxDuration":30,"energyLevel":1,"intensity":1,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["각자 좋아하는 곡 하나 추천하기","무료로 가능한 곡을 짧게 듣기","처음 들은 기억이나 좋아하는 이유 말하기"],"constraints":["작은 음량으로 듣고 구독·결제·계정 공유는 하지 않아요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('family-library-explore', '{"id":"family-library-explore","version":1,"title":"도서관에서 서로의 책 찾기","emoji":"📚","shortDescription":"서로 좋아할 제목 하나씩.","fullDescription":"도보 왕복 20분 안에 무료 이용 가능한 공공도서관이 열려 있는지 확인해요. 책을 빌리거나 회원가입하지 않고 각자 다른 가족이 좋아할 책 제목을 하나 찾아 조용히 보여줘요.","category":"exploration","allowedRelationships":["family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":30,"maxDuration":60,"energyLevel":2,"intensity":2,"travelScope":"nearby","indoor":true,"outdoor":false,"nightSafe":false,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":2,"locationRequired":true,"difficulty":1,"estimatedFun":3,"baseExp":100,"steps":["가까운 무료 도서관의 운영·이용 조건 확인하기","서로 좋아할 책 제목 하나씩 찾기","작은 목소리로 이유를 말하고 돌아오기"],"constraints":["어린이는 보호자와 함께하고 도서관의 이용 규칙을 따라요","회원가입·결제·대출 없이 공개 열람 가능한 곳에서만 해요","대기 포함 1시간 안에 왕복 가능할 때만 진행해요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb),
('family-living-room-trip', '{"id":"family-living-room-trip","version":1,"title":"거실에서 떠나는 우주여행","emoji":"🚀","shortDescription":"탑승권 대신 상상력만 준비해요.","fullDescription":"편한 자리에 앉아 각자 우주선의 역할 하나를 맡아요. 가상의 목적지 이름과 거기서 먹을 음식, 만날 동물을 돌아가며 상상해요. 마지막에 우주선의 이름을 정해요.","category":"random","allowedRelationships":["family"],"minPeople":2,"maxPeople":null,"minBudget":0,"maxBudget":0,"minDuration":5,"maxDuration":15,"energyLevel":1,"intensity":4,"travelScope":"home","indoor":true,"outdoor":false,"nightSafe":true,"soloSafe":true,"familySafe":true,"minorSafe":true,"requiresCar":false,"alcoholRelated":false,"physicalRiskLevel":0,"physicalIntensity":1,"locationRequired":false,"difficulty":2,"estimatedFun":4,"baseExp":100,"steps":["앉아서 각자의 가상 역할 정하기","목적지·음식·동물을 돌아가며 상상하기","우주선 이름 정하고 여행 마무리하기"],"constraints":["가구를 옮기거나 올라가거나 뛰지 않아요","큰 소리·물건 던지기 없이 말이나 그림으로 즐겨요"],"active":true,"createdAt":"2026-10-06T00:00:00.000Z"}'::jsonb)
